{
    Super::BeginPlay();

    Capture = MakeUnique<Audio::FAudioCapture>();

    Audio::FAudioCaptureStreamParam Params;
    Params.DeviceIndex = INDEX_NONE; // Default input device
    Params.NumFramesDesired = 1024;

    Params.Callback =
        [](const float* AudioData, int32 NumFrames, int32 NumChannels,
           int32 SampleRate, double StreamTime, bool bOverflow)
        {
            // AudioData contains captured audio for this callback.
            // Copy/process it safely here; avoid accessing UObjects directly
            // from the audio callback thread.
        };

    if (!Capture->OpenDefaultCaptureStream(Params) || !Capture->StartStream())
    {
        UE_LOG(LogTemp, Error, TEXT("Could not start audio capture"));
        Capture->CloseStream();
        Capture.Reset();
    }
}

